import limited_client as robot, numpy as np
from PIL import Image
for c in (2,0):
 o=robot.observe(camera=c); Image.fromarray(o['rgb']).save(f'/app/output/object_scan_{c}.png')
 print('CAM',c,'STATUS',robot.status(),'ROBOT',o['robot'])
 D=o['depth_m']; K=o['intrinsic']; T=o['camera_to_world']; I=o['rgb']
 if c==2:
  points={'row1':(148,232),'row4':(228,232),'row6':(258,232),'dark_fallen':(279,255),'dark_fallen2':(285,255),'table_adjacent':(290,255),'mat':(330,350)}
 else:
  points={'faceup_near':(143,338),'dark_near':(190,328),'row_front':(245,330),'mat':(285,300)}
 for name,(u,v) in points.items():
  z=float(np.nanmedian(D[v-2:v+3,u-2:u+3])); p=np.linalg.inv(K)@np.array([u,v,1.])*z
  print(name,'uv',(u,v),'rgb',I[v,u].tolist(),'depth',z,'world',(T@np.r_[p,1.])[:3])
